:: 话题对话
<div class="story-panel">
    <div id="dialogueContent"></div>

    <<script>>
    var topicId = State.variables.currentTopic;
    var dialogue = window.topicDialogues[topicId];
    if (!dialogue) {
        Engine.play(State.variables.returnPassage);
        return;
    }

    var node = State.variables.dialogueNode || "start";
    var data = dialogue[node];
    if (!data) data = dialogue.start;

    var name = State.variables.dialogueChar === "leiDe" ? State.variables.initialName : "K";
    var text = typeof data.text === "function" ? data.text(name) : data.text;
    var html = `<p>${text}</p>`;

    if (data.options && data.options.length > 0) {
        html += `<div style="margin-top:10px;"><strong>你的回答：</strong></div>`;
        for (var i = 0; i < data.options.length; i++) {
            var opt = data.options[i];
            html += `<br>[[${opt.text}|话题选择][$dialogueChoice = ${i}]]`;
        }
    } else if (data.next === "end") {
        html += `<br><br>[[离开|话题对话结束]]`;
    } else {
        State.variables.dialogueNode = data.next;
        Engine.play("话题对话");
        return;
    }

    jQuery("#dialogueContent").html(html);
    <</script>>
</div>
